options.getOption:
// Keep selection in Grafana's variable state so the detail panels update in place.
const chart = context.panel.chart;
const theme = context.grafana.theme;
const groups = [
  { le: '0.0001', name: '≤100µs', color: 'green' },
  { le: '0.0005', name: '100–500µs', color: 'blue' },
  { le: '0.002', name: '500µs–2ms', color: 'yellow' },
  { le: '0.016', name: '2–16ms', color: 'orange' },
  { le: '0.128', name: '16–128ms', color: 'red' },
  { le: '+Inf', name: '>128ms', color: 'purple' },
];
const from = Number(context.grafana.replaceVariables('${__from}'));
const to = Number(context.grafana.replaceVariables('${__to}'));
const duration = (to - from) / 1000;
const steps = [60, 120, 300, 600, 900, 1800, 3600, 7200, 14400, 21600, 43200, 86400];
const step = duration <= 900 ? 0 :
  (steps.find((value) => value >= duration / 100) ?? Math.ceil(duration / 8640000) * 86400);
// A partial edge window must not shrink the inferred width of every bar.
const barWidth = step ? Math.max(4, Math.min(36, (chart.getWidth() - 100) * step / duration * 0.7)) : undefined;
const counts = new Map();
for (const frame of context.panel.data.series) {
  const time = frame.fields.find((field) => field.type === 'time');
  const count = frame.fields.find((field) => field.type === 'number');
  const group = groups.findIndex((group) => group.le === count?.labels?.le);
  if (!time || !count || group < 0) {
    continue;
  }
  for (let index = 0; index < time.values.length; index++) {
    const timestamp = time.values[index];
    const value = count.values[index];
    if (Number.isFinite(timestamp) && Number.isFinite(value)) {
      const cumulative = counts.get(timestamp) ?? Array(groups.length).fill(null);
      cumulative[group] = (cumulative[group] ?? 0) + value;
      counts.set(timestamp, cumulative);
    }
  }
}
// Only complete samples can be decumulated; absent buckets are not zero IO.
const samples = [...counts]
  .filter(([timestamp, cumulative]) => timestamp > from && timestamp <= to &&
    cumulative.every((value, index) =>
      Number.isFinite(value) && (index === 0 || value >= cumulative[index - 1])))
  .sort((left, right) => left[0] - right[0]);
const periods = new Map();
for (const [timestamp, cumulative] of samples) {
  // Overview and detail both filter raw samples to (start, end].
  const boundary = step ? Math.ceil(timestamp / (step * 1000)) * step * 1000 : timestamp;
  const end = Math.min(boundary, to);
  const start = step ? Math.max(boundary - step * 1000, from) : timestamp;
  const point = periods.get(end) ?? { time: end, start, cumulative: Array(groups.length).fill(0) };
  cumulative.forEach((value, index) => point.cumulative[index] += value);
  periods.set(end, point);
}
// Keep zero-IO periods for detail selection, but draw only positive totals.
const allPeriods = [...periods.values()];
const points = allPeriods.filter((point) => point.cumulative.at(-1) > 0);
const sample = context.grafana.replaceVariables('${iolatency_sample_time:raw}');
const selectedTime = Math.round(Number(sample) * 1000);
const selected = points.find((point) => step ?
  selectedTime > point.start && selectedTime <= point.time : point.time === selectedTime) ?? points.at(-1) ?? allPeriods.at(-1);
const select = (point) => {
  const end = point?.time ?? 0;
  // Prometheus timestamps have millisecond precision. A single-sample
  // window excludes every earlier sample, including other series' old data.
  const start = point ? (step ? point.start : end - 1) : 0;
  const selection = {
    'var-iolatency_sample_time': (end / 1000).toFixed(3),
    'var-iolatency_sample_start': String(start),
    'var-iolatency_window': `${Math.max(1, Math.round(end - start))}ms`,
  };
  if (Object.entries(selection).some(([key, value]) =>
    context.grafana.replaceVariables('${' + key.slice(4) + ':raw}') !== value)) {
    context.grafana.locationService.partial(selection, true);
  }
};
// No valid selection uses the empty window (0, 0], clearing both details.
select(selected);
const timezone = context.grafana.replaceVariables('${__timezone}');
const clock = new Intl.DateTimeFormat('en-US', {
  timeZone: timezone === 'utc' ? 'UTC' : timezone,
  ...(duration > 86400 ? { month: '2-digit', day: '2-digit' } : {}),
  hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false,
});
const data = (timestamp) => points.map((point) => ({
  value: [point.time, point.cumulative.at(-1)],
  itemStyle: {
    color: 'transparent',
    borderWidth: point.time === timestamp ? (step ? 1 : 2) : 0,
    borderColor: theme.colors.text.primary,
  },
}));
const selectPeriod = (params) => {
  const point = periods.get(params.value[0]);
  if (point) {
    chart.setOption({ series: [{ id: 'io-total', data: data(point.time) }] });
    select(point);
  }
};
chart.on('click', { seriesId: 'io-total' }, selectPeriod);
const interval = step >= 3600 ? `${step / 3600} h` : `${step / 60} min`;
return {
  version: 2,
  unsubscribe: () => chart.off('click', selectPeriod),
  option: {
    animation: false,
    aria: { enabled: true },
    grid: { left: 12, right: 24, top: 48, bottom: 60, containLabel: true },
    legend: {
      bottom: 8, selectedMode: false,
      data: groups.map((group) => group.name),
      textStyle: { color: theme.colors.text.primary },
    },
    textStyle: { color: theme.colors.text.primary, fontFamily: theme.typography.fontFamily },
    title: points.length ? {
      text: step ? `${interval} per bar · Total IO count` : 'One collection interval per bar',
      left: 12, top: 4,
      textStyle: { color: theme.colors.text.secondary, fontSize: 12, fontWeight: 'normal' },
    } : {
      text: allPeriods.length ? 'No IO in collected intervals' : 'No complete samples in the selected time range', left: 'center', top: 'middle',
      textStyle: { color: theme.colors.text.secondary, fontSize: 14 },
    },
    tooltip: {
      trigger: 'axis', axisPointer: { type: 'shadow' },
      formatter: (items) => {
        const total = items.find((item) => item.seriesId === 'io-total');
        const point = periods.get(total.value[0]);
        const time = step ? `${clock.format(point.start)}–${clock.format(point.time)}` : clock.format(point.time);
        return `${time}<br/>Total IO: ${total.value[1]}<br/>` +
          items.filter((item) => item.seriesId !== 'io-total')
            .map((item) => `${item.marker}${item.seriesName}: ${item.value[1]}`).join('<br/>');
      },
    },
    xAxis: {
      type: 'time', min: from, max: to,
      axisLabel: { formatter: (value) => clock.format(value), hideOverlap: true },
      axisLine: { lineStyle: { color: theme.colors.border.weak } },
      splitLine: { show: false },
    },
    yAxis: {
      type: 'value', min: 0, minInterval: 1, name: 'IO Count',
      splitLine: { lineStyle: { color: theme.colors.border.weak } },
    },
    series: [...groups.map((group, index) => ({
      id: `io-group-${index}`, name: group.name, type: 'bar', stack: 'latency',
      barWidth, barMaxWidth: 36, silent: true,
      itemStyle: { color: theme.visualization.getColorByName(group.color) },
      data: points.map((point) => [point.time,
        point.cumulative[index] - (index ? point.cumulative[index - 1] : 0)]),
    })), {
      // A transparent overlay preserves the bucket colors and gives the whole bar one click target.
      id: 'io-total', name: 'Total IO', type: 'bar', z: 3, barGap: '-100%',
      barWidth, barMaxWidth: 36, barMinHeight: 4, emphasis: { disabled: true },
      label: { show: true, position: 'top', formatter: (params) => `${params.value[1]}` },
      data: data(selected?.time),
    }],
  },
};
